import{_ as e,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Redimensionar colunas das listas","description":"","frontmatter":{"title":"Redimensionar colunas das listas","id":"eproc-redimensionar-colunas-listas","plataforma":"eproc","grupo":"Relatórios","plano":"free","desde":"1.15.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-redimensionar-colunas-listas"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-redimensionar-colunas-listas"}],["meta",{"property":"og:title","content":"Redimensionar colunas das listas | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-redimensionar-colunas-listas.md","filePath":"funcionalidades/eproc-redimensionar-colunas-listas.md"}'),l={name:"funcionalidades/eproc-redimensionar-colunas-listas.md"};function i(n,a,t,d,c,u){return o(),r("div",null,a[0]||(a[0]=[s('<h1 id="redimensionar-colunas-das-listas" tabindex="-1">Redimensionar colunas das listas <a class="header-anchor" href="#redimensionar-colunas-das-listas" aria-label="Permalink to &quot;Redimensionar colunas das listas&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Permite alargar ou estreitar as colunas das listas de processos e de localizadores arrastando a borda do cabeçalho, como numa planilha. As larguras ficam guardadas e voltam na próxima vez que você abrir a tela.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, nas telas:</p><ul><li><strong>Relatório Geral de Processos</strong>;</li><li><strong>Lista de Processos por Localizador</strong>;</li><li><strong>Meus Localizadores</strong> e as demais listagens de localizadores.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Passe o mouse na borda direita do cabeçalho de uma coluna. O cursor vira uma seta dupla e uma linha azul aparece na borda.</li><li>Clique e arraste para a direita para alargar a coluna, ou para a esquerda para estreitá-la. Durante o arraste, a largura aparece em pixels junto ao cursor.</li><li>Solte o botão. A largura fica guardada.</li><li>Para voltar à largura original da coluna, dê um duplo clique na mesma borda.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>As larguras são guardadas separadamente para cada tela e para cada perfil/unidade do eproc.</li><li>No Relatório Geral, a largura acompanha a coluna mesmo que você mude as &quot;Colunas visíveis&quot;.</li><li>Ao alargar uma coluna, as outras se ajustam para caber na tabela. Uma coluna não fica mais estreita que a palavra mais longa dela.</li><li>Clicar na borda não ordena a tabela; para ordenar, clique no nome da coluna, como antes.</li></ul>',12)]))}const h=e(l,[["render",i]]);export{m as __pageData,h as default};
